// Corps envoyé par le bot.
const body = $json.body ?? $json;
const text = String(body.text ?? '');
const command = (text.trim().split(/\s+/)[0] || '').toLowerCase();
const args = text.replace(/^\/\S+\s*/, '').trim();

// Le bot a déjà parsé ET résolu la cible : ses champs font foi. Le repli sur le
// texte n'existe que pour encaisser un payload plus ancien.
const flagIdx = args.search(/(?:^|\s)--/);
const startupFallback = (flagIdx === -1 ? args : args.slice(0, flagIdx)).trim();
const domMatch = args.match(/--domaine\s+("[^"]+"|'[^']+'|(?!--)\S+)/i);
const modMatch = /(?:^|\s)--mod[eé]rateur\b/i.test(args);
// Répétition générale : on déroule tout sauf l'invitation elle-même.
const simMatch = /(?:^|\s)--(?:simuler|simulation|dry-run)\b/i.test(args);
const unquote = (s) => String(s ?? '').replace(/^["']|["']$/g, '').trim();

return [{ json: {
  command,
  args,
  text,
  sender: body.sender ?? '',
  roomId: body.roomId ?? '',
  isDM: body.isDM ?? false,
  managedSpace: body.managedSpace ?? '',
  startup: unquote(body.startup || startupFallback),
  domaine: unquote(body.domaine || (domMatch ? domMatch[1] : '')),
  moderateur: body.moderateur === true || modMatch,
  simuler: body.simuler === true || simMatch,
  targetRoomId: body.targetRoomId ?? '',
  targetLabel: body.targetLabel ?? '',
  homeserver: String(body.homeserver ?? '').replace(/\/$/, ''),
} }];

// Filtre startup + domaine, déduplique, émet un item par personne à inviter.
// Distingue « startup inconnue » de « bon nom mais aucun membre pour ce
// domaine », pour que le message aval soit juste. Reçoit TOUS les membres,
// donc s'exécute toujours : c'est ce qui rend la branche « aucun » atteignable.
const p = $('Parse').first().json;
const norm = (s) => String(s ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().trim();

const startup = norm(p.startup);
const domaine = norm(p.domaine);
const simuler = p.simuler === true;

const all = $input.all().map(i => i.json);
const inStartup = all.filter(m => norm(m.ghid) === startup);
const matched = inStartup.filter(
  m => domaine === '' || norm(m.domaine).startsWith(domaine),
);

const mxids = [...new Set(
  matched.map(m => String(m.matrix_id ?? '').trim()).filter(Boolean),
)];

if (mxids.length === 0) {
  const raison = inStartup.length === 0 ? 'startup' : 'domaine';
  return [{ json: { aucun: true, raison, simuler } }];
}

// Filet de sécurité : en simulation, on vide le salon cible. Le branchement du
// IF « Simulation ? » suffirait, mais s'il était un jour mal recâblé le POST
// partirait sur une URL sans salon et échouerait — aucune invitation ne peut
// sortir par accident.
return mxids.map(mxid => ({
  json: {
    mxid,
    simuler,
    targetRoomId: simuler ? '' : p.targetRoomId,
    homeserver: p.homeserver,
  },
}));

// Message quand personne n'est invité. Deux causes distinctes.
const p = $('Parse').first().json;
const raison = ($input.first().json ?? {}).raison || 'startup';

const norm = (s) => String(s ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().trim();

// Reconstruit la commande en gardant les options. p.text n'a plus la mention
// (le bot l'a retirée) : ex. "/invite xy --espace --domaine dev".
const text = String(p.text ?? '');
const m = text.match(/^\/invite\s+(.*?)(\s+--.*)?$/s);
const flags = (m && m[2]) ? m[2] : '';
const prefix = p.isDM ? '' : '@betabot ';
const cmd = (nom) => `${prefix}/invite ${nom}${flags}`;
// Variante sans le filtre domaine, pour la suggestion « inviter tout le monde ».
const flagsSansDomaine = flags.replace(/\s+--domaine\s+("[^"]+"|'[^']+'|(?!--)\S+)/i, '');
const cmdTous = (nom) => `${prefix}/invite ${nom}${flagsSansDomaine}`;

// Startup trouvée, mais le filtre domaine exclut tout le monde.
if (raison === 'domaine') {
  const s = norm(p.startup);
  const domaines = [...new Set(
    $('Explore espace-membre').all().map(i => i.json)
      .filter(x => norm(x.ghid) === s)
      .map(x => String(x.domaine ?? '').trim())
      .filter(Boolean),
  )].sort();
  const liste = domaines.length
    ? domaines.map(d => `**${d}**`).join(', ')
    : 'aucun domaine renseigné';
  return [{ json: {
    reaction: '🔎',
    message:
      `🔎 Startup **${p.startup}** trouvée, mais personne avec le domaine ` +
      `**${p.domaine}**.\nDomaines disponibles : ${liste}.\n` +
      `Pour inviter tout le monde :\n\`${cmdTous(p.startup)}\``,
  } }];
}

// Startup introuvable : cherche le ghid le plus proche.
const target = norm(p.startup);
const ghids = [...new Set(
  $('Explore espace-membre').all()
    .map(i => String(i.json.ghid ?? '').trim()).filter(Boolean),
)];

const lev = (a, b) => {
  const M = a.length, N = b.length;
  const dp = Array.from({ length: M + 1 }, () => new Array(N + 1).fill(0));
  for (let i = 0; i <= M; i++) dp[i][0] = i;
  for (let j = 0; j <= N; j++) dp[0][j] = j;
  for (let i = 1; i <= M; i++) for (let j = 1; j <= N; j++)
    dp[i][j] = Math.min(
      dp[i - 1][j] + 1, dp[i][j - 1] + 1,
      dp[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1),
    );
  return dp[M][N];
};

let best = null, bestD = Infinity;
for (const g of ghids) {
  const d = lev(target, norm(g));
  if (d < bestD) { bestD = d; best = g; }
}

// Ne propose que si vraiment proche, sinon on suggérerait n'importe quoi.
const seuil = Math.max(2, Math.floor(target.length * 0.4));
if (best && bestD <= seuil) {
  return [{ json: {
    reaction: '🤔',
    message:
      `🤔 Aucune startup **${p.startup}**. Tu voulais peut-être dire ` +
      `**${best}** ?\nSi oui, copie :\n\`${cmd(best)}\``,
  } }];
}

return [{ json: {
  reaction: '📭',
  message:
    `📭 Aucune startup **${p.startup}** (ni nom approchant). Vérifie ` +
    `l'orthographe — c'est le *ghid* de la startup.`,
} }];

// Répétition générale : la sélection a été faite pour de vrai, l'invitation
// n'est pas envoyée. C'est le seul chemin qui peut dire QUI serait invité,
// puisque la liste vit ici et pas dans le bot.
const p = $('Parse').first().json;

const mxids = [...new Set(
  $input.all().map(i => String(i.json.mxid ?? '').trim()).filter(Boolean),
)];

const cible = p.targetLabel || 'le salon ciblé';
const filtre = p.domaine ? ` (domaine **${p.domaine}**)` : '';
const liste = mxids.map(m => `- \`${m}\``).join('\n');

const lignes = [
  `🧪 **Simulation** — aucune invitation envoyée.`,
  ``,
  `**${mxids.length}** membre(s) de **${p.startup}**${filtre} seraient invités dans ${cible} :`,
  ``,
  liste,
];

if (p.moderateur === true) {
  lignes.push(``, `🛡️ Chacun serait aussi passé **modérateur** (niveau 50).`);
}

lignes.push(``, `Pour l'exécuter réellement, retire \`--simuler\`.`);

return [{ json: { message: lignes.join('\n'), reaction: '🧪' } }];

// Fusionne les nouveaux modérateurs dans l'event m.room.power_levels.
// UNE seule écriture pour tout le monde : cet event porte la map complète, donc
// une écriture par personne repartirait d'une version périmée et écraserait la
// précédente.
const entree = $input.first().json ?? {};

// « Lire power_levels » est en continueRegularOutput : son échec arrive ici
// sous forme d'item d'erreur. Il ne faut SURTOUT pas écrire dans ce cas — un
// PUT construit sur une lecture manquante remplacerait la map complète des
// pouvoirs du salon et rétrograderait tout le monde, admins compris.
const lectureRatee =
  !!entree.error ||
  typeof entree !== 'object' ||
  (!('users' in entree) && !('users_default' in entree));

if (lectureRatee) {
  const e = entree.error;
  const msg = e
    ? String(e.message || e.reason || JSON.stringify(e)).slice(0, 160)
    : 'réponse inattendue du homeserver (pas de champ users)';
  return [{ json: { _lectureOk: false, _erreurLecture: msg } }];
}

const pl = entree;
const users = { ...(pl.users ?? {}) };
const defaut = pl.users_default ?? 0;

// On promeut toute la sélection, y compris ceux dont l'invitation a échoué
// parce qu'ils étaient déjà dans le salon.
const mxids = $('Membres -> items').all()
  .map(i => String(i.json.mxid ?? '').trim())
  .filter(Boolean);

let promus = 0;
for (const m of mxids) {
  const actuel = users[m] ?? defaut;
  // Ne jamais rétrograder : un admin à 100 doit le rester.
  if (actuel < 50) { users[m] = 50; promus++; }
}

return [{ json: { ...pl, users, _lectureOk: true, _promus: promus } }];

// Compte succès / déjà présent / échec, remonte la raison des échecs, et
// signale la promotion modérateur quand elle a été demandée.
const NODE_PARSE   = 'Parse';
const NODE_INVITER = 'Inviter (Matrix)';
const NODE_FUSION  = 'Fusionner power_levels';
const NODE_ECRIRE  = 'Écrire power_levels';

const p = $(NODE_PARSE).first().json;

// Lecture explicite des invitations : avec --moderateur, l'entrée de ce node
// vient du PUT power_levels, plus des invitations. $input.all() ne compterait
// alors que la réponse de l'écriture des pouvoirs.
let resultats;
try { resultats = $(NODE_INVITER).all(); } catch (e) { resultats = $input.all(); }

let invited = 0, already = 0, failed = 0;
const raisons = new Set();
for (const it of resultats) {
  const j = it.json ?? {};
  if (!j.error) { invited++; continue; }
  const e = j.error;
  const msg = String((e && (e.message || e.reason)) || JSON.stringify(e ?? {}));
  // « déjà dans le salon » est un 403 attendu ; les autres 403 (le bot n'a pas
  // le droit d'inviter) doivent rester visibles.
  if (/already in the room|already joined/i.test(msg)) already++;
  else { failed++; raisons.add(msg.slice(0, 120)); }
}

// Promotion : ces nodes n'existent dans l'exécution que si --moderateur.
let promus = null, promoErreur = null;
if (p.moderateur === true) {
  let fusion = null;
  try { fusion = $(NODE_FUSION).first().json ?? null; } catch (e) { fusion = null; }
  // Lecture des pouvoirs ratée : l'écriture a été volontairement sautée.
  if (fusion && fusion._lectureOk === false) {
    promoErreur = `lecture des pouvoirs impossible — ${fusion._erreurLecture}`;
  } else {
    promus = fusion ? (fusion._promus ?? 0) : null;
    try {
      const w = $(NODE_ECRIRE).first().json ?? {};
      if (w.error) {
        const we = w.error;
        promoErreur = String((we && (we.message || we.reason)) || JSON.stringify(we));
      }
    } catch (e) { /* node non exécuté */ }
  }
}

const parts = [`✅ ${invited} invité(s) dans ${p.targetLabel || 'le salon'}`];
if (already) parts.push(`${already} déjà présent(s)`);
if (failed)  parts.push(`❌ ${failed} échec(s)`);
if (p.moderateur === true) {
  if (promoErreur)          parts.push(`❌ promotion modérateur échouée`);
  else if (promus !== null) parts.push(`🛡️ ${promus} passé(s) modérateur`);
}

let message = parts.join(' · ');
const details = [...raisons];
if (promoErreur) details.push(`power_levels : ${promoErreur.slice(0, 160)}`);
if (details.length) message += `\n\nDétail : ${details.join(' | ')}`;

const reaction = (failed || promoErreur) ? '⚠️' : (invited > 0 ? '✅' : '📭');
return [{ json: { message, reaction } }];
